function rampartSimulate(createStrategy, seed, maxTicks, hook) {
  'use strict';
  // ---- static rules -------------------------------------------------------
  var TYPE_NAMES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var TUR = {
    bolt:   { cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, ground: 1, air: 1 },
    cannon: { cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: 0, ground: 1, air: 0 },
    frost:  { cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: 0, ground: 1, air: 1 },
    lance:  { cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, ground: 1, air: 0 },
    flak:   { cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: 0, ground: 0, air: 1 }
  };
  // enemy kinds in table order (index 6 = splitling, never drawn)
  var EN = [
    { name: 'grunt',    hp: 60,  speed: 10, bounty: 4, leak: 1, route: 0, first: 1, weight: 10 },
    { name: 'runner',   hp: 40,  speed: 20, bounty: 4, leak: 1, route: 0, first: 2, weight: 4 },
    { name: 'wisp',     hp: 50,  speed: 12, bounty: 6, leak: 2, route: 1, first: 3, weight: 3 },
    { name: 'brute',    hp: 150, speed: 6,  bounty: 9, leak: 3, route: 0, first: 4, weight: 3 },
    { name: 'splitter', hp: 90,  speed: 8,  bounty: 6, leak: 2, route: 0, first: 6, weight: 2 },
    { name: 'mender',   hp: 70,  speed: 8,  bounty: 7, leak: 2, route: 0, first: 8, weight: 1 },
    { name: 'splitling', hp: 0,  speed: 12, bounty: 1, leak: 1, route: 0, first: 99, weight: 0 }
  ];
  var SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8],
                    [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var ROUTE_TILES = [
    [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]],
    [[0, 6], [21, 6], [21, 11], [23, 11]]
  ];
  // ---- route lookup tables (position for each integer progress) -----------
  var ROUTE_LEN = [0, 0], PX = [[], []], PY = [[], []];
  (function () {
    for (var r = 0; r < 2; r++) {
      var pts = ROUTE_TILES[r], p = 0;
      for (var i = 0; i + 1 < pts.length; i++) {
        var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50;
        var bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
        var segLen = Math.abs(bx - ax) + Math.abs(by - ay);
        var sx = bx > ax ? 1 : bx < ax ? -1 : 0, sy = by > ay ? 1 : by < ay ? -1 : 0;
        for (var d = 0; d < segLen; d++) { PX[r][p] = ax + sx * d; PY[r][p] = ay + sy * d; p++; }
        if (i + 2 === pts.length) { PX[r][p] = bx; PY[r][p] = by; }
      }
      ROUTE_LEN[r] = p;
    }
  })();

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  var strat = createStrategy();
  var rng = mulberry32(seed);
  var log = [];
  var waveComps = [null];      // waveComps[w] = array of kind indices
  var multTable = [0, 1000];   // m(w)
  function mult(w) { while (multTable.length <= w) multTable.push(Math.floor(multTable[multTable.length - 1] * 108 / 100)); return multTable[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), pool = [], total = 0, out = [];
    for (var k = 0; k < 6; k++) if (EN[k].first <= w) { pool.push(k); total += EN[k].weight; }
    for (var i = 0; i < n; i++) {
      var r = rng() % total, j = 0;
      while (r >= EN[pool[j]].weight) { r -= EN[pool[j]].weight; j++; }
      out.push(pool[j]);
    }
    return out;
  }
  function ensureWave(w) { while (waveComps.length <= w) waveComps.push(genWave(waveComps.length)); }

  // ---- game state ----------------------------------------------------------
  var baseHp = 10, gold = 250, nextId = 1, wave = 0;
  var enemies = [];
  var slots = [];
  for (var si = 0; si < 16; si++) slots.push(null);
  var active = []; // spawning waves: { w, start, n, next }
  var fellTick = -1;

  function makeEnemy(kind, w, maxHp, progress) {
    var k = EN[kind], armor = 0;
    if (kind === 0) armor = Math.floor(w / 4); else if (kind === 3) armor = 6 + w;
    return { id: nextId++, kind: kind, wave: w, maxHp: maxHp, hp: maxHp, progress: progress, age: 0, slow: 0,
             armor: armor, route: k.route, len: ROUTE_LEN[k.route], speed: k.speed, bounty: k.bounty, leak: k.leak };
  }
  function viewOf(e) {
    var p = e.progress >= e.len ? e.len : e.progress;
    return { id: e.id, type: EN[e.kind].name, hp: e.hp, maxHp: e.maxHp, x: PX[e.route][p], y: PY[e.route][p],
             air: e.route, armor: e.armor, speed: e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed,
             slowed: e.slow > 0 ? 1 : 0, remaining: e.len - e.progress };
  }
  function turretDamage(type, tier) {
    var d = TUR[type].dmg;
    if (tier >= 2) d = Math.floor(d * 16 / 10);
    if (tier >= 3) d = Math.floor(d * 16 / 10);
    return d;
  }
  function makeState(w, tick) {
    var sl = [], i, en = [];
    for (i = 0; i < 16; i++) {
      var t = slots[i];
      sl.push({ slot: i, x: SLOT_TILES[i][0], y: SLOT_TILES[i][1],
                turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null });
    }
    for (i = 0; i < enemies.length; i++) en.push(viewOf(enemies[i]));
    var nw = [], nc = waveComps[w + 1];
    for (i = 0; i < nc.length; i++) nw.push(EN[nc[i]].name);
    return { tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: sl, enemies: en, nextWave: nw };
  }

  var rec = null;
  function applyActions(acts, tick) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(acts.length, 32);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== 'object') continue;
      var s = a.slot;
      if (typeof s !== 'number' || s !== Math.floor(s) || s < 0 || s > 15) continue;
      if (a.op === 'build') {
        if (slots[s] || !Object.prototype.hasOwnProperty.call(TUR, a.type)) continue;
        var spec = TUR[a.type];
        if (gold < spec.cost) continue;
        gold -= spec.cost;
        slots[s] = { type: a.type, tier: 1, spent: spec.cost, cd: 0, dmg: spec.dmg, range: spec.range };
        log.push([tick, 'B', s, TYPE_NAMES.indexOf(a.type)]);
        if (rec) rec.acts.push([0, s, TYPE_NAMES.indexOf(a.type), 1]);
      } else if (a.op === 'upgrade') {
        var t = slots[s];
        if (!t || t.tier >= 3) continue;
        var c = TUR[t.type].cost * (t.tier === 1 ? 1 : 2);
        if (gold < c) continue;
        gold -= c; t.spent += c; t.tier++;
        t.dmg = turretDamage(t.type, t.tier); t.range = TUR[t.type].range + 30 * (t.tier - 1);
        log.push([tick, 'U', s, t.tier]);
        if (rec) rec.acts.push([1, s, TYPE_NAMES.indexOf(t.type), t.tier]);
      } else if (a.op === 'sell') {
        var u = slots[s];
        if (!u) continue;
        gold += Math.floor(u.spent * 70 / 100);
        slots[s] = null;
        log.push([tick, 'S', s, 0]);
        if (rec) rec.acts.push([2, s, TYPE_NAMES.indexOf(u.type), u.tier]);
      }
    }
  }

  function killDead(tick, slotIdx) {
    var out = null, i, e;
    for (i = 0; i < enemies.length; i++) { if (enemies[i].hp <= 0) { out = true; break; } }
    if (!out) return;
    var list = enemies.slice(), keep = [];
    enemies = keep;
    // enemies array is rebuilt; splitlings are appended with new (larger) ids
    for (i = 0; i < list.length; i++) {
      e = list[i];
      if (e.hp > 0) { keep.push(e); continue; }
      gold += e.bounty;
      log.push([tick, 'K', e.id, slotIdx]);
      if (rec) rec.kills.push([e.id, e.kind, e.route, e.progress, e.wave, slotIdx]);
      if (e.kind === 4) {
        var h = Math.max(1, Math.floor(e.maxHp / 4));
        for (var j = 0; j < 3; j++) keep.push(makeEnemy(6, e.wave, h, e.progress));
      }
    }
  }

  var strategyTarget = typeof strat.target === 'function';
  var lastWave = 0;

  for (var tick = 0; tick < maxTicks; tick++) {
    if (hook) rec = { acts: [], shots: [], kills: [], heals: [], leaks: [], spawns: [] };
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      wave = w; lastWave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      ensureWave(w + 1);
      var acts = strat.plan(makeState(w, tick));
      applyActions(acts, tick);
      active.push({ w: w, start: tick, n: waveComps[w].length, next: 0 });
    }
    // 2. spawn
    for (var ai = 0; ai < active.length; ai++) {
      var aw = active[ai];
      while (aw.next < aw.n && aw.start + 4 * aw.next <= tick) {
        var kind = waveComps[aw.w][aw.next];
        var mh = Math.floor(EN[kind].hp * mult(aw.w) / 1000);
        var ne = makeEnemy(kind, aw.w, mh, 0);
        enemies.push(ne);
        if (rec) rec.spawns.push(ne.id);
        aw.next++;
      }
    }
    while (active.length && active[0].next >= active[0].n) active.shift();
    // 3. move
    var fell = false;
    for (var mi = 0; mi < enemies.length; mi++) {
      var me = enemies[mi];
      me.progress += me.slow > 0 ? Math.floor(me.speed * 60 / 100) : me.speed;
      if (me.progress >= me.len) {
        baseHp -= me.leak;
        log.push([tick, 'L', me.id, baseHp]);
        if (rec) rec.leaks.push([me.id, me.kind, me.route, me.leak, baseHp]);
        me.hp = -999999; me.leaked = true;
        if (baseHp <= 0) { fell = true; break; }
      }
    }
    if (fell) {
      log.push([tick, 'F', wave, 0]);
      fellTick = tick;
      if (hook) { rec.fell = true; finishTick(tick); }
      break;
    }
    if (enemies.some(function (q) { return q.leaked; })) enemies = enemies.filter(function (q) { return !q.leaked; });
    // 4. age & heal
    for (var hi = 0; hi < enemies.length; hi++) {
      var he = enemies[hi];
      he.age++;
      if (he.kind === 5 && he.age % 20 === 0) {
        var hx = PX[he.route][he.progress], hy = PY[he.route][he.progress];
        if (rec) rec.heals.push([he.id, hx, hy]);
        for (var hj = 0; hj < enemies.length; hj++) {
          var o = enemies[hj];
          var dx = PX[o.route][o.progress] - hx, dy = PY[o.route][o.progress] - hy;
          if (dx * dx + dy * dy <= 150 * 150) {
            var heal = Math.floor(o.maxHp * 8 / 100);
            o.hp = Math.min(o.maxHp, o.hp + heal);
          }
        }
      }
    }
    // 5. turrets fire
    for (var ti = 0; ti < 16; ti++) {
      var tu = slots[ti];
      if (!tu) continue;
      if (tu.cd > 0) tu.cd--;
      if (tu.cd > 0) continue;
      var spec2 = TUR[tu.type];
      var tx = SLOT_TILES[ti][0] * 100 + 50, ty = SLOT_TILES[ti][1] * 100 + 50;
      var r2 = tu.range * tu.range;
      var cands = [];
      for (var ci = 0; ci < enemies.length; ci++) {
        var ce = enemies[ci];
        if (ce.route === 1 ? !spec2.air : !spec2.ground) continue;
        var cx = PX[ce.route][ce.progress] - tx, cy = PY[ce.route][ce.progress] - ty;
        if (cx * cx + cy * cy <= r2) cands.push(ce);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (strategyTarget) {
        var views = [];
        for (var vi = 0; vi < cands.length; vi++) views.push(viewOf(cands[vi]));
        var pick = strat.target({ slot: ti, type: tu.type, tier: tu.tier, x: tx, y: ty, range: tu.range }, views);
        for (var pi = 0; pi < cands.length; pi++) if (cands[pi].id === pick) { tgt = cands[pi]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        var best = tgt.len - tgt.progress;
        for (var bi = 1; bi < cands.length; bi++) {
          var rem = cands[bi].len - cands[bi].progress;
          if (rem < best) { best = rem; tgt = cands[bi]; }
        }
      }
      var gx = PX[tgt.route][tgt.progress], gy = PY[tgt.route][tgt.progress];
      var dmg = tu.dmg;
      if (rec) rec.shots.push([ti, TYPE_NAMES.indexOf(tu.type), tgt.id, gx, gy, tgt.route, tu.tier]);
      if (spec2.splash > 0) {
        var sr2 = spec2.splash * spec2.splash;
        for (var ei = 0; ei < enemies.length; ei++) {
          var se = enemies[ei];
          if (se.route === 1 ? !spec2.air : !spec2.ground) continue;
          var sx = PX[se.route][se.progress] - gx, sy = PY[se.route][se.progress] - gy;
          if (sx * sx + sy * sy <= sr2) {
            se.hp -= spec2.pierce ? dmg : Math.max(1, dmg - se.armor);
            if (spec2.slow) se.slow = spec2.slow;
          }
        }
      } else {
        tgt.hp -= spec2.pierce ? dmg : Math.max(1, dmg - tgt.armor);
        if (spec2.slow) tgt.slow = spec2.slow;
      }
      tu.cd = spec2.period;
      killDead(tick, ti);
    }
    // 6. slow timers
    for (var qi = 0; qi < enemies.length; qi++) if (enemies[qi].slow > 0) enemies[qi].slow--;
    if (hook) finishTick(tick);
  }

  function finishTick(tk) {
    rec.tick = tk; rec.wave = wave; rec.gold = gold; rec.baseHp = baseHp;
    rec.enemies = enemies; rec.slots = slots;
    rec.nextWave = waveComps[wave + 1] || null;
    rec.wavesComp = waveComps;
    hook(rec);
  }

  var endTick = fellTick >= 0 ? fellTick : maxTicks;
  var score = Math.round((endTick - 20) / 40 * 100) / 100;
  var js = JSON.stringify(log), h = 0x811c9dc5;
  for (var ci2 = 0; ci2 < js.length; ci2++) { h ^= js.charCodeAt(ci2); h = Math.imul(h, 0x01000193); }
  var hash = (h >>> 0).toString(16);
  while (hash.length < 8) hash = '0' + hash;
  return { score: score, fallTick: fellTick, log: log, hash: hash };
}

