function createStrategy() {
  'use strict';
  // Tuned parameters (found by offline search over many seeds).
  var G = /*GENOME*/ null;
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var BASE_DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var SPLASH = { bolt: 0, cannon: 90, frost: 0, lance: 0, flak: 70 };
  var HITS_AIR = { bolt: 1, cannon: 0, frost: 1, lance: 0, flak: 1 };
  var HITS_GND = { bolt: 1, cannon: 1, frost: 1, lance: 1, flak: 0 };
  var PIERCE = { bolt: 0, cannon: 0, frost: 0, lance: 1, flak: 0 };
  var Q = G.q;
  var ptr = 0;

  function tierDmg(type, tier) {
    var d = BASE_DMG[type];
    if (tier >= 2) d = Math.floor(d * 16 / 10);
    if (tier >= 3) d = Math.floor(d * 16 / 10);
    return d;
  }

  function plan(state) {
    var acts = [];
    var wave = state.wave;
    var res = G.res[0] + G.res[1] * wave;
    if (res < 0) res = 0;
    var gold = state.gold;
    var sl = [];
    for (var i = 0; i < 16; i++) {
      var t = state.slots[i].turret;
      sl.push(t ? { type: t.type, tier: t.tier, spent: t.spent } : null);
    }
    var guard = 0;
    while (ptr < Q.length && acts.length < 32 && guard++ < 200) {
      var st = Q[ptr];
      var op = st[0], slot = st[1], type = TYPES[st[2]];
      if (st[3] > wave) break;
      var cur = sl[slot];
      if (op === 0) {
        if (cur) { ptr++; continue; }
        var c = COST[type];
        if (gold - c < res) break;
        gold -= c;
        sl[slot] = { type: type, tier: 1, spent: c };
        acts.push({ op: 'build', slot: slot, type: type });
        ptr++;
      } else if (op === 1) {
        if (!cur || cur.tier >= 3) { ptr++; continue; }
        var uc = COST[cur.type] * (cur.tier === 1 ? 1 : 2);
        if (gold - uc < res) break;
        gold -= uc;
        cur.tier++; cur.spent += uc;
        acts.push({ op: 'upgrade', slot: slot });
        ptr++;
      } else {
        if (!cur) { ptr++; continue; }
        gold += Math.floor(cur.spent * 70 / 100);
        sl[slot] = null;
        acts.push({ op: 'sell', slot: slot });
        ptr++;
      }
    }
    return acts;
  }

  function target(turret, cands) {
    var type = turret.type;
    var W = G.tw[type];
    if (!W) return -1;
    var n = cands.length;
    if (n === 1) return cands[0].id;
    var dmg = tierDmg(type, turret.tier);
    var splash = SPLASH[type];
    var s2 = splash * splash;
    var pierce = PIERCE[type];
    var maxHp = 1, i, j, e;
    for (i = 0; i < n; i++) if (cands[i].hp > maxHp) maxHp = cands[i].hp;
    var best = -1, bestScore = -1e18, bestRem = 1e9;
    for (i = 0; i < n; i++) {
      e = cands[i];
      var len = e.air ? 2800 : 4600;
      var eff = pierce ? dmg : Math.max(1, dmg - e.armor);
      var f0 = (len - e.remaining) / len;
      var f1 = e.type === 'mender' ? 1 : 0;
      var f2 = e.slowed ? 0 : 1;
      var f3 = e.hp / maxHp;
      var f4 = eff >= e.hp ? 1 : 0;
      var f5 = Math.min(e.armor, 40) / 20;
      var f6 = e.type === 'brute' ? 1 : (e.type === 'splitter' || e.type === 'wisp' || e.type === 'mender') ? 0.5 : 0;
      var f7 = 0, f8 = 0;
      if (splash > 0) {
        var cnt = 0, tot = 0;
        for (j = 0; j < n; j++) {
          var o = cands[j];
          var dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= s2) {
            cnt++;
            var oe = pierce ? dmg : Math.max(1, dmg - o.armor);
            tot += oe < o.hp ? oe : o.hp;
          }
        }
        f7 = cnt / 5;
        f8 = tot / (dmg * 5);
      } else {
        f8 = (eff < e.hp ? eff : e.hp) / dmg;
      }
      var f9 = eff > e.hp ? (eff - e.hp) / eff : 0;
      var sc = W[0] * f0 + W[1] * f1 + W[2] * f2 + W[3] * f3 + W[4] * f4 + W[5] * f5 + W[6] * f6 + W[7] * f7 + W[8] * f8 + W[9] * f9;
      if (sc > bestScore + 1e-9 || (sc > bestScore - 1e-9 && e.remaining < bestRem)) {
        bestScore = sc; best = e.id; bestRem = e.remaining;
      }
    }
    return best;
  }

  return { plan: plan, target: target };
}

