function createStrategy() {
  'use strict';
  // Tuned parameters (found by offline search over many seeds).
  var G = /*GENOME*/ null;
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var BASE_DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var SPLASH = { bolt: 0, cannon: 90, frost: 0, lance: 0, flak: 70 };
  var HITS_AIR = { bolt: 1, cannon: 0, frost: 1, lance: 0, flak: 1 };
  var HITS_GND = { bolt: 1, cannon: 1, frost: 1, lance: 1, flak: 0 };
  var PIERCE = { bolt: 0, cannon: 0, frost: 0, lance: 1, flak: 0 };
  var Q = G.q;
  var ptr = 0;

  function tierDmg(type, tier) {
    var d = BASE_DMG[type];
    if (tier >= 2) d = Math.floor(d * 16 / 10);
    if (tier >= 3) d = Math.floor(d * 16 / 10);
    return d;
  }

  function plan(state) {
    var acts = [];
    var wave = state.wave;
    var res = G.res[0] + G.res[1] * wave;
    if (res < 0) res = 0;
    var gold = state.gold;
    var sl = [];
    for (var i = 0; i < 16; i++) {
      var t = state.slots[i].turret;
      sl.push(t ? { type: t.type, tier: t.tier, spent: t.spent } : null);
    }
    var guard = 0;
    while (ptr < Q.length && acts.length < 32 && guard++ < 200) {
      var st = Q[ptr];
      var op = st[0], slot = st[1], type = TYPES[st[2]];
      if (st[3] > wave) break;
      var cur = sl[slot];
      if (op === 0) {
        if (cur) { ptr++; continue; }
        var c = COST[type];
        if (gold - c < res) break;
        gold -= c;
        sl[slot] = { type: type, tier: 1, spent: c };
        acts.push({ op: 'build', slot: slot, type: type });
        ptr++;
