        if (!cur || cur.tier >= 3) { ptr++; continue; }
        var uc = COST[cur.type] * (cur.tier === 1 ? 1 : 2);
        if (gold - uc < res) break;
        gold -= uc;
        cur.tier++; cur.spent += uc;
        acts.push({ op: 'upgrade', slot: slot });
        ptr++;
      } else {
        if (!cur) { ptr++; continue; }
        gold += Math.floor(cur.spent * 70 / 100);
