const { Worker } = require('worker_threads');
const path = require('path');
class Pool {
  constructor(n) {
    this.workers = []; this.idle = []; this.queue = []; this.pending = new Map(); this.nextId = 1;
    for (let i = 0; i < n; i++) {
      const w = new Worker(path.join(__dirname, 'worker.js'));
      w.on('message', (m) => {
        const p = this.pending.get(m.id); this.pending.delete(m.id);
        this.idle.push(w); this._pump();
        if (m.error) p.reject(new Error(m.error)); else p.resolve(m.scores);
      });
      w.on('error', (e) => { console.error('worker error', e); });
      this.workers.push(w); this.idle.push(w);
    }
  }
  _pump() {
    while (this.idle.length && this.queue.length) {
      const w = this.idle.pop(); const t = this.queue.shift();
      this.pending.set(t.msg.id, t); w.postMessage(t.msg);
    }
  }
  run(genome, seeds, maxTicks) {
    return new Promise((resolve, reject) => {
      const id = this.nextId++;
      this.queue.push({ msg: { id, genome, seeds, maxTicks }, resolve, reject });
      this._pump();
    });
  }
  // mean score over seeds, split in chunks for parallelism
  async evalMean(genome, seeds, chunks) {
    chunks = chunks || 1;
    const per = Math.ceil(seeds.length / chunks);
    const parts = [];
    for (let i = 0; i < seeds.length; i += per) parts.push(this.run(genome, seeds.slice(i, i + per)));
    const res = (await Promise.all(parts)).flat();
    return res;
  }
  close() { for (const w of this.workers) w.terminate(); }
}
module.exports = { Pool };

