      var he = enemies[hi];
      he.age++;
      if (he.kind === 5 && he.age % 20 === 0) {
        var hx = PX[he.route][he.progress], hy = PY[he.route][he.progress];
        if (rec) rec.heals.push([he.id, hx, hy]);
        for (var hj = 0; hj < enemies.length; hj++) {
          var o = enemies[hj];
          var dx = PX[o.route][o.progress] - hx, dy = PY[o.route][o.progress] - hy;
          if (dx * dx + dy * dy <= 150 * 150) {
            var heal = Math.floor(o.maxHp * 8 / 100);
            o.hp = Math.min(o.maxHp, o.hp + heal);
          }
        }
      }
    }
