const args = Object.fromEntries(process.argv.slice(2).map(a => { const [k, v] = a.split('='); return [k, v]; }));
const TAG = args.tag || 'a';
const MINUTES = parseFloat(args.minutes || '10');
const MU = parseInt(args.mu || '6');
const LAMBDA = parseInt(args.lambda || '36');
