/* ---------- instanced pools ---------- */
function makePool(geo, mat, cap, castShadow) {
  const im = new THREE.InstancedMesh(geo, mat, cap);
  im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  im.setColorAt(0, new THREE.Color(1, 1, 1));
  im.instanceColor.setUsage(THREE.DynamicDrawUsage);
  im.frustumCulled = false; im.count = 0; im.castShadow = !!castShadow;
  scene.add(im);
  return { mesh: im, cap: cap, n: 0, m: im.instanceMatrix.array, c: im.instanceColor.array };
}
function poolBegin(p) { p.n = 0; }
function poolEnd(p) { p.mesh.count = p.n; p.mesh.instanceMatrix.needsUpdate = true; p.mesh.instanceColor.needsUpdate = true; }
function putYaw(p, x, y, z, yaw, sx, sy, sz, r, g, b) {
