  m[o + 8] = s * sz; m[o + 9] = 0; m[o + 10] = c * sz; m[o + 11] = 0;
  m[o + 12] = x; m[o + 13] = y; m[o + 14] = z; m[o + 15] = 1;
  const k = p.n * 3; p.c[k] = r; p.c[k + 1] = g; p.c[k + 2] = b; p.n++;
}
function putBill(p, x, y, z, sx, sy, r, g, b) {     // camera-facing quad
  if (p.n >= p.cap) return;
  const q = camera.quaternion, qx = q.x, qy = q.y, qz = q.z, qw = q.w;
