/* ---------- startup: replay, self-check, report ---------- */
const REPLAY = buildReplay();

function selfCheck() {
  const out = { vectorA: false, vectorB: false };
  try {
    const A = function () { return { plan: function (s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return a; } }; };
    const ra = rampartSimulate(A, 42, 12020);
    out.vectorA = ra.score === 25.38 && ra.fallTick === 1035 && ra.log.length === 166 && ra.hash === '82a5353d';
    const B = function () { return { plan: function (s) {
      if (s.wave === 1) return [{ op: 'build', slot: 3, type: 'cannon' }, { op: 'build', slot: 6, type: 'frost' }];
      if (s.wave === 3) return [{ op: 'upgrade', slot: 3 }, { op: 'build', slot: 12, type: 'flak' }];
      if (s.wave === 6) return [{ op: 'build', slot: 8, type: 'lance' }, { op: 'sell', slot: 6 }];
      return [];
    } }; };
    const rb = rampartSimulate(B, 7, 12020);
    out.vectorB = rb.score === 10.93 && rb.fallTick === 457 && rb.log.length === 48 && rb.hash === '2e8858d7';
  } catch (e) { /* leave false */ }
  return out;
}
window.BENCH_REPORT = {
  selfCheck: selfCheck(),
  strategy: {
    summary: /*STRATEGY_SUMMARY*/ '',
    seedsTested: /*SEEDS_TESTED*/ 0,
    meanScoreOnTestedSeeds: /*MEAN_SCORE*/ null
  },
  seed42: { score: REPLAY.result.score, fallTick: REPLAY.result.fallTick },
  systems: {
    board: 'full', enemiesAndTurrets: 'full', combatVisuals: 'full', fall: 'full', hud: 'full', audio: 'full'
  },
  simplifications: /*SIMPLIFICATIONS*/ [],
  testedInBrowser: false,
  measuredFps: null
};

/* ---------- playback state machine ---------- */
const elCountdown = document.getElementById('countdown');
const elToggle = document.getElementById('btn-toggle');
const elRefire = document.getElementById('btn-refire');
const elPause = document.getElementById('icon-pause');
const elPlay = document.getElementById('icon-play');
const elScrub = document.getElementById('scrubber');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

let state = 'INIT';            // INIT -> COUNTDOWN | PLAYING | PAUSED | REFIRE_HOLD | ENDED
let simTime = 0, playbackSpeed = 1, countdownElapsed = 0, holdElapsed = 0, lastNow = null, dragging = false;

function showCountdown(txt) { elCountdown.style.display = 'block'; elCountdown.textContent = txt; }
function hideCountdown() { elCountdown.style.display = 'none'; elCountdown.textContent = ''; }
function setIcons(playing) {
  elPause.style.display = playing ? '' : 'none';
  elPlay.style.display = playing ? 'none' : '';
  elToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function setScrub(v) { elScrub.value = v; }
function renderAt(t) { renderFrame(REPLAY, t); drawHUD(REPLAY, t); }
function syncAudio() {
  const on = state === 'PLAYING' && !dragging;
  Snd.setAudible(on);
  Snd.wind(on && REPLAY.fell && simTime >= REPLAY.fallTick / TPS + 1.0);
}

function enterPlaying() { state = 'PLAYING'; setIcons(true); syncAudio(); }
function enterPaused() { state = 'PAUSED'; setIcons(false); syncAudio(); }
function enterEnded() { state = 'ENDED'; simTime = DURATION; setScrub(DURATION.toFixed(3)); setIcons(false); syncAudio(); }

function advancePlaying(dtScaled) {
  const prev = simTime;
  simTime = Math.min(DURATION, simTime + dtScaled);
  setScrub(simTime.toFixed(3));
  Snd.advance(REPLAY, prev, simTime);
  if (simTime >= DURATION) enterEnded();
}

elToggle.addEventListener('click', function () {
  if (state === 'PLAYING') enterPaused();
  else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD' || state === 'INIT') { hideCountdown(); simTime = 0; setScrub('0'); enterPaused(); renderAt(simTime); }
  else if (state === 'PAUSED') enterPlaying();
  else if (state === 'ENDED') { simTime = 0; setScrub('0'); hideCountdown(); enterPlaying(); renderAt(simTime); }
});
elRefire.addEventListener('click', function () {
  hideCountdown(); simTime = 0; setScrub('0'); countdownElapsed = 0; holdElapsed = 0; dragging = false;
  state = 'REFIRE_HOLD'; setIcons(true); syncAudio(); renderAt(0);
});
pills.forEach(function (p) {
  p.addEventListener('click', function () {
    playbackSpeed = parseFloat(p.getAttribute('data-speed'));
    pills.forEach(function (q) { const on = q === p; q.classList.toggle('is-active', on); q.setAttribute('aria-checked', on ? 'true' : 'false'); });
  });
});
elScrub.addEventListener('pointerdown', function () { dragging = true; syncAudio(); });
window.addEventListener('pointerup', function () { if (dragging) { dragging = false; syncAudio(); } });
elScrub.addEventListener('input', function () {
  hideCountdown();
  simTime = clamp(parseFloat(elScrub.value) || 0, 0, DURATION);
  dragging = true; enterPaused();
  renderAt(simTime);
});
elScrub.addEventListener('change', function () { dragging = false; syncAudio(); });

function frame(now) {
  requestAnimationFrame(frame);
  const rawDt = lastNow === null ? 0 : Math.max(0, (now - lastNow) / 1000);
  lastNow = now;
  const dt = Math.min(rawDt, 0.1);
  if (state === 'INIT') {
    state = 'COUNTDOWN'; countdownElapsed = 0; showCountdown('3'); setIcons(true);
  } else if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) {
      const left = countdownElapsed - 3.0;
      hideCountdown(); enterPlaying(); advancePlaying(left * playbackSpeed);
    } else showCountdown(countdownElapsed < 1.0 ? '3' : countdownElapsed < 2.0 ? '2' : '1');
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) { const left = holdElapsed - 1.0; enterPlaying(); advancePlaying(left * playbackSpeed); }
  } else if (state === 'PLAYING') {
    advancePlaying(dt * playbackSpeed);
  }
  syncAudio();
  renderAt(simTime);
}

function onResize() {
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  frameCamera();
  HUD.resize(window.innerWidth, window.innerHeight);
  renderAt(simTime);
}
window.addEventListener('resize', onResize);

HUD.resize(window.innerWidth, window.innerHeight);
setIcons(true);
renderAt(0);                       // initial resting scene (simTime = 0.000)
window.__rampart = { get state() { return state; }, get simTime() { return simTime; }, get speed() { return playbackSpeed; }, replay: REPLAY, renderAt: renderAt };
requestAnimationFrame(frame);

