const fs = require('fs');
const path = require('path');
const D = __dirname;
const rd = (f) => fs.readFileSync(path.join(D, f), 'utf8');
const args = Object.fromEntries(process.argv.slice(2).map(a => { const i = a.indexOf('='); return [a.slice(0, i), a.slice(i + 1)]; }));
const genome = JSON.parse(rd(args.genome || 'best_final.json'));
const meta = fs.existsSync(path.join(D, 'meta.json')) ? JSON.parse(rd('meta.json')) : { summary: '', seedsTested: 0, mean: null, simplifications: [] };
const outPath = args.out || path.join(D, 'out', 'index.html');

let strategy = rd('strat_tpl.js').replace('/*GENOME*/ null', () => JSON.stringify(genome));
let sim = rd('sim.js');
let main = ['main_1.js', 'main_2.js', 'main_3.js', 'main_4.js', 'main_5.js', 'main_6.js'].map(rd).join('\n');
main = main.replace("/*STRATEGY_SUMMARY*/ ''", () => JSON.stringify(meta.summary))
  .replace('/*SEEDS_TESTED*/ 0', () => String(meta.seedsTested))
  .replace('/*MEAN_SCORE*/ null', () => String(meta.mean))
  .replace('/*SIMPLIFICATIONS*/ []', () => JSON.stringify(meta.simplifications));
let html = rd('template.html');
html = html.replace('/*STRATEGY*/', () => strategy).replace('/*SIM*/', () => sim).replace('/*MAIN*/', () => main);
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, html);
console.log('wrote', outPath, html.length, 'bytes');
// sanity: forbidden tokens inside the strategy script
for (const tok of ['Math.random', 'Date', 'performance', 'window', 'document', 'THREE']) if (strategy.includes(tok)) console.log('WARNING strategy contains', tok);
for (const tok of ['document', 'THREE', 'window', 'Audio']) if (sim.includes(tok)) console.log('WARNING sim contains', tok);

