// Drives the page headlessly: state machine, DOM contract and per-frame rendering sanity.
const vm = require('vm');
const h = require('./harness.js');
const { els, pills } = h;
const get = (expr) => vm.runInThisContext(expr);
let fails = 0;
function check(name, cond, extra) { if (!cond) { fails++; console.log('FAIL', name, extra === undefined ? '' : extra); } else console.log('ok  ', name); }
let now = 1000;
function frame(dtMs) { now += dtMs; h.rafCb(now); }
const st = () => get('__rampart.state'), sim = () => get('__rampart.simTime');

// --- initial state
check('initial countdown text', els.countdown.textContent === '3' && els.countdown.style.display !== 'none');
check('scrubber initial', els.scrubber.value === '0');
// --- countdown: first rAF starts COUNTDOWN with elapsed 0
frame(16); check('first frame enters COUNTDOWN', st() === 'COUNTDOWN');
let elapsed = 0; const seen = new Set();
while (elapsed < 2.97) { frame(16.667); elapsed += 0.016667; seen.add(els.countdown.textContent); }
check('countdown shows 3,2,1', seen.has('3') && seen.has('2') && seen.has('1') && st() === 'COUNTDOWN', [...seen].join(','));
check('simTime still 0 during countdown', sim() === 0 && els.scrubber.value === '0');
for (let i = 0; i < 5; i++) frame(16.667);
check('countdown hidden after 3s', els.countdown.style.display === 'none' && els.countdown.textContent === '' && st() === 'PLAYING', st());
check('simTime advancing', sim() > 0 && sim() < 0.2, sim());
check('pause icon visible while playing', els['icon-play'].style.display === 'none' && els['btn-toggle']._attrs['aria-label'] === 'Pause');
// --- pause / play
els['btn-toggle'].fire('click'); check('toggle -> PAUSED', st() === 'PAUSED' && els['icon-play'].style.display === '' && els['icon-pause'].style.display === 'none' && els['btn-toggle']._attrs['aria-label'] === 'Play');
const t1 = sim(); for (let i = 0; i < 10; i++) frame(16.667); check('frozen while paused', sim() === t1);
els['btn-toggle'].fire('click'); check('toggle -> PLAYING', st() === 'PLAYING' && els['btn-toggle']._attrs['aria-label'] === 'Pause');
// --- speed
pills[3].fire('click'); check('speed 2x', get('__rampart.speed') === 2 && pills[3]._attrs['aria-checked'] === 'true' && pills[2]._attrs['aria-checked'] === 'false' && pills[3].classList.contains('is-active') && !pills[2].classList.contains('is-active'));
const t2 = sim(); frame(16.667); check('2x advances 2dt', Math.abs(sim() - t2 - 0.033333) < 1e-4, sim() - t2);
pills[2].fire('click');
// --- scrubbing
els.scrubber.value = '55.5'; els.scrubber.fire('input');
check('scrub -> PAUSED at 55.5', st() === 'PAUSED' && Math.abs(sim() - 55.5) < 1e-9);
// --- toggle then play to the end at 2x
els['btn-toggle'].fire('click'); pills[3].fire('click');
let guard = 0; while (st() === 'PLAYING' && guard++ < 5000) frame(33.4);
check('ENDED at 100', st() === 'ENDED' && sim() === 100 && els.scrubber.value === '100.000' && els['icon-play'].style.display === '' && els['btn-toggle']._attrs['aria-label'] === 'Play', [st(), sim(), els.scrubber.value]);
els['btn-toggle'].fire('click'); check('ENDED toggle restarts', st() === 'PLAYING' && sim() === 0 && els.countdown.style.display === 'none');
// --- refire
for (let i = 0; i < 30; i++) frame(33.4);
els['btn-refire'].fire('click'); check('refire -> REFIRE_HOLD', st() === 'REFIRE_HOLD' && sim() === 0 && els.scrubber.value === '0' && els.countdown.style.display === 'none');
for (let i = 0; i < 20; i++) frame(33.4); check('hold keeps simTime 0', st() === 'REFIRE_HOLD' && sim() === 0);
for (let i = 0; i < 20; i++) frame(33.4); check('hold -> PLAYING after 1s', st() === 'PLAYING' && sim() > 0, [st(), sim()]);
els['btn-refire'].fire('click'); els['btn-toggle'].fire('click');
check('toggle during hold -> PAUSED', st() === 'PAUSED' && sim() === 0);

// --- render sweep: finite instance data everywhere
const scene = get('scene'), renderAt = get('__rampart.renderAt');
let bad = 0, maxInst = {};
for (let t = 0; t <= 100.0001; t += 0.37) {
  renderAt(Math.min(100, t));
  scene.traverse((o) => {
    if (o.isInstancedMesh) {
      const n = o.count * 16, a = o.instanceMatrix.array;
      for (let i = 0; i < n; i++) if (!Number.isFinite(a[i])) { bad++; break; }
      const c = o.instanceColor.array; for (let i = 0; i < o.count * 3; i++) if (!Number.isFinite(c[i])) { bad++; break; }
      maxInst[o.uuid] = Math.max(maxInst[o.uuid] || 0, o.count);
    }
  });
}
check('no NaN in instance buffers', bad === 0, bad);
renderAt(0); renderAt(100); renderAt(50.005);
const R = get('REPLAY');
console.log('replay: last tick', R.last, 'fell', R.fell, 'fallTick', R.fallTick, 'score', R.result.score, 'hash', R.result.hash);
console.log('BENCH_REPORT', JSON.stringify(get('window.BENCH_REPORT')));
console.log('max pool cap usage:', Object.values(maxInst).sort((a, b) => b - a).slice(0, 8).join(','));
console.log(fails ? 'FAILURES: ' + fails : 'ALL OK', 'drawCalls', h.drawCalls);

