// Crude software rasteriser of the real scene graph (after renderFrame updates it) to sanity check composition.
const vm = require('vm');
const fs = require('fs');
const zlib = require('zlib');
const h = require('./harness.js');
const get = (e) => vm.runInThisContext(e);
const THREE = globalThis.THREE;

function crc32(buf) { let c, crc = -1; for (let n = 0; n < buf.length; n++) { c = (crc ^ buf[n]) & 0xff; for (let k = 0; k < 8; k++) c = c & 1 ? (c >>> 1) ^ 0xEDB88320 : c >>> 1; crc = (crc >>> 8) ^ c; } return (crc ^ -1) >>> 0; }
function chunk(type, data) { const len = Buffer.alloc(4); len.writeUInt32BE(data.length); const td = Buffer.concat([Buffer.from(type), data]); const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td)); return Buffer.concat([len, td, crc]); }
function writePNG(file, w, hgt, rgb) {
  const raw = Buffer.alloc((w * 3 + 1) * hgt);
  for (let y = 0; y < hgt; y++) { raw[y * (w * 3 + 1)] = 0; rgb.copy(raw, y * (w * 3 + 1) + 1, y * w * 3, (y + 1) * w * 3); }
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(hgt, 4); ihdr[8] = 8; ihdr[9] = 2;
  fs.writeFileSync(file, Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]));
}
function aces(x) { const a = 2.51, b = 0.03, c = 2.43, d = 0.59, e = 0.14; const v = (x * (a * x + b)) / (x * (c * x + d) + e); return Math.max(0, Math.min(1, v)); }

function preview(t, file, SW, SH, opts) {
  opts = opts || {};
  const renderAt = get('__rampart.renderAt'); renderAt(t);
  const scene = get('scene'), camera = get('camera'), sun = get('sun'), glowTex = get('glowTex'), blobTex = get('blobTex');
  const grey = get('greyU').value;
  scene.updateMatrixWorld(true); camera.updateMatrixWorld(true);
  const VP = new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse);
  const color = new Float32Array(SW * SH * 3), depth = new Float32Array(SW * SH).fill(1e9);
  for (let y = 0; y < SH; y++) for (let x = 0; x < SW; x++) { const dx = (x / SW - 0.5), dy = (y / SH - 0.5), d = Math.min(1, Math.sqrt(dx * dx + dy * dy) * 1.4); const i = (y * SW + x) * 3; color[i] = (0.086 - d * 0.05) ; color[i + 1] = (0.098 - d * 0.056); color[i + 2] = (0.14 - d * 0.08); }
  const L = new THREE.Vector3().copy(sun.position).sub(sun.target.position).normalize();
  const list = [];
  scene.traverse((o) => {
    if (!o.isMesh) return;
    let p = o; while (p) { if (!p.visible) return; p = p.parent; }
    list.push(o);
  });
  const isAdd = (o) => o.material.blending === THREE.AdditiveBlending;
  const isTrans = (o) => o.material.transparent && !isAdd(o);
  list.sort((a, b) => ((isAdd(a) ? 2 : isTrans(a) ? 1 : 0) - (isAdd(b) ? 2 : isTrans(b) ? 1 : 0)) || (a.renderOrder - b.renderOrder));
  const v4 = new THREE.Vector4(), tmp = new THREE.Matrix4(), mm = new THREE.Matrix4(), nm = new THREE.Matrix3();
  let tris = 0;
  function drawMesh(o) {
    const mat = o.material, geo = o.geometry, pos = geo.attributes.position, nor = geo.attributes.normal, col = geo.attributes.color, uvA = geo.attributes.uv;
    const idx = geo.index ? geo.index.array : null;
    const nInst = o.isInstancedMesh ? o.count : 1;
