    const unlit = mat.isMeshBasicMaterial || mat.isShaderMaterial;
    const add = isAdd(o), trans = isTrans(o);
    const base = mat.color ? [mat.color.r, mat.color.g, mat.color.b] : [1, 1, 1];
    let avg = null;
    if (mat.map && mat.map !== glowTex && mat.map !== blobTex && !mat.isMeshBasicMaterial) avg = mat.map.repeat && mat.map.repeat.x === 6 ? [0.045, 0.065, 0.025] : [0.07, 0.07, 0.08];
    const nVerts = idx ? idx.length : pos.count;
    for (let ii = 0; ii < nInst; ii++) {
      if (o.isInstancedMesh) { tmp.fromArray(o.instanceMatrix.array, ii * 16); mm.multiplyMatrices(o.matrixWorld, tmp); } else mm.copy(o.matrixWorld);
      nm.getNormalMatrix(mm);
