      const MVP = new THREE.Matrix4().multiplyMatrices(VP, mm);
      for (let t3 = 0; t3 < nVerts; t3 += 3) {
        const sv = [];
        let ok = true;
        for (let k = 0; k < 3; k++) {
          const vi = idx ? idx[t3 + k] : t3 + k;
          v4.set(pos.getX(vi), pos.getY(vi), pos.getZ(vi), 1).applyMatrix4(MVP);
          if (v4.w < 0.2) { ok = false; break; }
          let c;
          if (avg) c = avg.slice(); else {
            c = useVC ? [col.getX(vi), col.getY(vi), col.getZ(vi)] : [1, 1, 1];
            c = [c[0] * base[0] * ic[0], c[1] * base[1] * ic[1], c[2] * base[2] * ic[2]];
          }
          let lit = 1;
          if (!unlit && nor) {
            const n = new THREE.Vector3(nor.getX(vi), nor.getY(vi), nor.getZ(vi)).applyMatrix3(nm).normalize();
            lit = 0.42 + 0.34 * (n.y * 0.5 + 0.5) + 1.25 * Math.max(0, n.dot(L));
            if (mat.emissive) { c[0] += mat.emissive.r * 2; }
          }
          sv.push({ x: (v4.x / v4.w * 0.5 + 0.5) * SW, y: (1 - (v4.y / v4.w * 0.5 + 0.5)) * SH, z: v4.z / v4.w, c: [c[0] * lit, c[1] * lit, c[2] * lit], u: uvA ? uvA.getX(vi) : 0, v: uvA ? uvA.getY(vi) : 0 });
        }
        if (!ok) continue;
        tris++;
        const [a, b, c] = sv;
        const minX = Math.max(0, Math.floor(Math.min(a.x, b.x, c.x))), maxX = Math.min(SW - 1, Math.ceil(Math.max(a.x, b.x, c.x)));
        const minY = Math.max(0, Math.floor(Math.min(a.y, b.y, c.y))), maxY = Math.min(SH - 1, Math.ceil(Math.max(a.y, b.y, c.y)));
        const area = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
        if (Math.abs(area) < 1e-6) continue;
        if (!(mat.side === THREE.DoubleSide) && !add && !trans && area > 0 && !o.isInstancedMesh) { /* keep both: handedness of flipped y */ }
        for (let y = minY; y <= maxY; y++) for (let x = minX; x <= maxX; x++) {
          const px = x + 0.5, py = y + 0.5;
          const w0 = ((b.x - px) * (c.y - py) - (b.y - py) * (c.x - px)) / area;
          const w1 = ((c.x - px) * (a.y - py) - (c.y - py) * (a.x - px)) / area;
          const w2 = 1 - w0 - w1;
          if (w0 < 0 || w1 < 0 || w2 < 0) continue;
          const z = a.z * w0 + b.z * w1 + c.z * w2;
          const di = y * SW + x;
          if (z > depth[di] + (trans || add ? 0 : 0)) continue;
          let r = a.c[0] * w0 + b.c[0] * w1 + c.c[0] * w2, g = a.c[1] * w0 + b.c[1] * w1 + c.c[1] * w2, bl = a.c[2] * w0 + b.c[2] * w1 + c.c[2] * w2;
          let alpha = 1;
          if (mat.map === glowTex || mat.map === blobTex) {
            const u = a.u * w0 + b.u * w1 + c.u * w2, v = a.v * w0 + b.v * w1 + c.v * w2, rr = Math.sqrt((u - 0.5) ** 2 + (v - 0.5) ** 2) * 2;
            alpha = rr >= 1 ? 0 : (1 - rr) * (1 - rr) * 1.3; if (mat.map === blobTex) { r = g = bl = 0; alpha *= 0.7; }
          }
          if (mat.opacity < 1) alpha *= mat.opacity;
          if (alpha <= 0.002) continue;
          const ci = di * 3;
          if (add) { color[ci] += r * alpha; color[ci + 1] += g * alpha; color[ci + 2] += bl * alpha; }
          else if (trans) { color[ci] = color[ci] * (1 - alpha) + r * alpha; color[ci + 1] = color[ci + 1] * (1 - alpha) + g * alpha; color[ci + 2] = color[ci + 2] * (1 - alpha) + bl * alpha; }
          else { color[ci] = r; color[ci + 1] = g; color[ci + 2] = bl; depth[di] = z; }
