  }
  for (const o of list) { if (o.material.isShaderMaterial && !o.geometry.attributes.uv && o.material === get('laneMat')) { /* lane drawn as cyan strip */ } drawMesh(o); }
  // tone map + gamma + desaturate
  const out = Buffer.alloc(SW * SH * 3);
  for (let i = 0; i < SW * SH; i++) {
    let r = color[i * 3], g = color[i * 3 + 1], b = color[i * 3 + 2];
