const vm = require('vm');
const h = require('./harness.js');
const get = (e) => vm.runInThisContext(e);
const W = parseInt(process.env.W || '1920'), H = parseInt(process.env.H || '1080');
const THREE = globalThis.THREE;
const cam = get('camera');
cam.updateMatrixWorld(true);
const pts = [[-0.5, 0, -0.5], [24.5, 0, -0.5], [24.5, 0, 14.5], [-0.5, 0, 14.5], [0, 0, 0], [24, 0, 14], [12, 0, 7], [23.5, 1.7, 11.5], [0.5, 0, 2.5]];
let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
for (const p of pts) {
  const v = new THREE.Vector3(...p).project(cam); const px = (v.x * 0.5 + 0.5) * W, py = (1 - (v.y * 0.5 + 0.5)) * H;
  console.log(p.join(','), '->', px.toFixed(0), py.toFixed(0));
}
for (const p of pts.slice(0, 4)) { const v = new THREE.Vector3(...p).project(cam); const px = (v.x * 0.5 + 0.5) * W, py = (1 - (v.y * 0.5 + 0.5)) * H; minX = Math.min(minX, px); maxX = Math.max(maxX, px); minY = Math.min(minY, py); maxY = Math.max(maxY, py); }
console.log(`viewport ${W}x${H}: board+margin bbox x ${minX.toFixed(0)}..${maxX.toFixed(0)} y ${minY.toFixed(0)}..${maxY.toFixed(0)}; dock zone starts y=${H - 90}; fits: ${minX >= 0 && maxX <= W && minY >= 0 && maxY <= H - 90}`);
const tilePx = new THREE.Vector3(12.5, 0, 7.5).project(cam), tilePx2 = new THREE.Vector3(13.5, 0, 7.5).project(cam);
console.log('tile width px at centre', ((tilePx2.x - tilePx.x) * 0.5 * W).toFixed(1));

