  HUD.icon(10, m, m + (waveH * 0.78 - iconS) / 2 + waveH * 0.04, iconS, 1, 1, 1);
  const wch = waveH * pulse;
  HUD.number(A.wave, m + iconS + 0.012 * H, m - (wch - waveH) * 0.5, wch, 1, 1, 1, 'left');
  // gold under the wave number
  const gy = m + waveH * 0.86, gS = 0.047 * H;
  HUD.icon(11, m, gy, gS, 1, 1, 1);
  HUD.number(A.gold, m + gS + 0.008 * H, gy - 0.012 * H, 0.074 * H, 1.0, 0.86, 0.35, 'left');
  // next-wave preview: coloured enemy icons with counts
  const cnt = nextWaveCounts(R, A.wave), py = gy + gS + 0.014 * H, pS = 0.04 * H;
  let px = m;
  for (let t = 0; t < 6; t++) {
    if (!cnt[t]) continue;
    HUD.icon(HUD_ENEMY_ICON[t], px, py, pS, 1, 1, 1); px += pS + 0.002 * H;
    px += HUD.number(cnt[t], px, py - 0.006 * H, 0.052 * H, 1, 1, 1, 'left') + 0.008 * H;
  }
  // base hp pips, top-right; lost pips flash
  const pipS = 0.034 * H, gap = 0.008 * H, total = 10 * pipS + 9 * gap;
  let x0 = W - m - total;
  const leaks = R.leaks;
  for (let p = 0; p < 10; p++) {
    const on = p < A.baseHp;
    let flash = 0;
    for (let i = 0; i < leaks.length; i++) {
      const l = leaks[i], a = (T - l.tick) / TPS;
      if (a < 0) break;
      if (p >= l.hpAfter && p < l.hpBefore && a < 0.6) flash = Math.max(flash, 1 - a / 0.6);
    }
    const px2 = x0 + p * (pipS + gap);
    if (on) HUD.icon(12, px2, m, pipS, 1, 1, 1);
    else {
      HUD.icon(13, px2, m, pipS, 1, 1, 1);
      if (flash > 0) { const gs = pipS * (1 + 0.6 * flash); HUD.icon(12, px2 - (gs - pipS) / 2, m - (gs - pipS) / 2, gs, 1.0, 0.25 + 0.4 * flash, 0.2 + 0.5 * flash); }
    }
  }
  HUD.end();
  renderer.clearDepth();
  renderer.render(HUD.scene, HUD.cam);
}

