const fs = require('fs');
const { Pool } = require('./pool.js');
const files = process.argv.slice(2).filter(a => !a.includes('='));
const args = Object.fromEntries(process.argv.slice(2).filter(a => a.includes('=')).map(a => a.split('=')));
const n = parseInt(args.n || '200'), s0 = parseInt(args.seed0 || '1000');
const seeds = Array.from({ length: n }, (_, i) => s0 + i);
(async () => {
  const pool = new Pool(parseInt(args.workers || '4'));
  for (const f of files) {
    const g = JSON.parse(fs.readFileSync(f, 'utf8'));
    const sc = await pool.evalMean(g, seeds, 8);
    const mean = sc.reduce((a, b) => a + b, 0) / sc.length;
    const sd = Math.sqrt(sc.reduce((a, b) => a + (b - mean) ** 2, 0) / sc.length);
    const sorted = sc.slice().sort((a, b) => a - b);
    console.log(f, 'mean', mean.toFixed(3), 'sd', sd.toFixed(2), 'min', sorted[0], 'p10', sorted[Math.floor(n * 0.1)], 'median', sorted[Math.floor(n / 2)], 'max', sorted[n - 1]);
  }
  pool.close();
})();

