  if (rec.tick >= 20 && (rec.tick - 20) % 40 === 0 || rec.fell) {
    const w = rec.wave;
    const sl = rec.slots.map(s => s ? T[['bolt','cannon','frost','lance','flak'].indexOf(s.type)] + s.tier : '--').join(' ');
    const cnt = {}; for (const e of rec.enemies) cnt[names[e.kind]] = (cnt[names[e.kind]] || 0) + 1;
    const hpSum = rec.enemies.reduce((a, e) => a + e.hp, 0);
    console.log(`w${w} t${rec.tick} gold ${rec.gold} hp ${rec.baseHp} n=${rec.enemies.length} hpSum=${hpSum} | ${sl}`);
  }
});
console.log(res.score, res.fallTick, res.hash);
const leaks = res.log.filter(e => e[1] === 'L');
