const fs = require('fs');
const { makeFactory, rampartSimulate } = require('./lib.js');
const g = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const f = makeFactory(g);
const rows = [];
for (let s = 3000; s < 3200; s++) {
  let comps = null;
  const r = rampartSimulate(f, s, 12020, (rec) => { comps = rec.wavesComp; });
  const lastW = Math.floor(r.score);
  // composition of waves 15..lastW-10 (the ones that decide the outcome)
  const c = [0, 0, 0, 0, 0, 0]; let tot = 0;
  for (let w = 15; w <= Math.max(16, lastW - 8); w++) if (comps[w]) for (const k of comps[w]) { c[k]++; tot++; }
  rows.push({ s, score: r.score, f: c.map(x => x / tot) });
}
function corr(a, b) { const n = a.length, ma = a.reduce((x, y) => x + y) / n, mb = b.reduce((x, y) => x + y) / n; let sab = 0, saa = 0, sbb = 0; for (let i = 0; i < n; i++) { sab += (a[i] - ma) * (b[i] - mb); saa += (a[i] - ma) ** 2; sbb += (b[i] - mb) ** 2; } return sab / Math.sqrt(saa * sbb); }
const names = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
for (let k = 0; k < 6; k++) console.log(names[k], 'corr with score', corr(rows.map(r => r.f[k]), rows.map(r => r.score)).toFixed(3));

