const TN = ['bolt', 'cannon', 'frost', 'lance', 'flak'];

function defaultGenome() {
  const q = [
    [0, 3, 0, 0], [0, 6, 0, 0], [0, 13, 0, 0],
    [0, 8, 1, 0], [0, 15, 0, 0],
    [1, 3, 0, 0], [1, 6, 0, 0],
    [0, 7, 1, 0], [0, 11, 1, 0], [0, 12, 0, 0],
    [1, 8, 0, 0], [1, 7, 0, 0], [1, 11, 0, 0],
    [0, 4, 3, 0], [0, 1, 0, 0], [0, 2, 1, 0], [0, 10, 0, 0],
    [1, 4, 0, 0], [1, 13, 0, 0], [1, 12, 0, 0],
    [1, 8, 0, 0], [1, 7, 0, 0], [1, 11, 0, 0], [1, 4, 0, 0], [1, 2, 0, 0], [1, 3, 0, 0], [1, 6, 0, 0],
  ];
