}
function clone(g) { return JSON.parse(JSON.stringify(g)); }

function macroMutate(g) {
  const q = g.q;
  const r = Math.random();
  if (r < 0.2) { // relabel: swap two slots everywhere
    const a = ri(16), b = ri(16);
    for (const s of q) { if (s[1] === a) s[1] = b; else if (s[1] === b) s[1] = a; }
