  const r = Math.random();
  if (r < 0.14) { // change type of a build
    const idx = q.map((s, i) => s[0] === 0 ? i : -1).filter(i => i >= 0);
    if (idx.length) q[idx[ri(idx.length)]][2] = ri(5);
  } else if (r < 0.30) { // change slot
    const i = ri(q.length); q[i][1] = ri(16);
