async function main() {
  const pool = new Pool(WORKERS);
  let init = INIT ? JSON.parse(fs.readFileSync(INIT, 'utf8')) : defaultGenome();
  const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;
  let popu = [];
  const s0 = mean(await pool.run(init, trainSeeds));
  popu.push({ g: init, s: s0 });
  console.log('init score', s0.toFixed(3));
  const t0 = Date.now();
  let gen = 0, bestEver = s0;
  while ((Date.now() - t0) / 60000 < MINUTES) {
    gen++;
    const kids = [];
    for (let i = 0; i < LAMBDA; i++) {
      // rank-biased parent selection
      const p = popu[Math.min(popu.length - 1, Math.floor(Math.pow(Math.random(), 1.8) * popu.length))];
      kids.push(mutate(p.g));
    }
    const scores = await Promise.all(kids.map(k => pool.run(k, trainSeeds).then(mean)));
    for (let i = 0; i < kids.length; i++) popu.push({ g: kids[i], s: scores[i] });
    popu.sort((a, b) => b.s - a.s);
