    const seen = new Set(); const nxt = [];
    for (const p of popu) { const key = p.s.toFixed(4); if (seen.has(key)) continue; seen.add(key); nxt.push(p); if (nxt.length >= MU) break; }
    popu = nxt;
    if (popu[0].s > bestEver + 1e-9) {
      bestEver = popu[0].s;
      fs.writeFileSync(path.join(__dirname, `best_${TAG}.json`), JSON.stringify(popu[0].g));
    }
    if (gen % 5 === 0 || gen === 1) console.log(`gen ${gen} t=${((Date.now() - t0) / 1000).toFixed(0)}s best ${popu[0].s.toFixed(3)} 2nd ${popu[1] ? popu[1].s.toFixed(3) : '-'} qlen ${popu[0].g.q.length}`);
  }
  fs.writeFileSync(path.join(__dirname, `best_${TAG}.json`), JSON.stringify(popu[0].g));
  console.log('done best', popu[0].s.toFixed(3));
  pool.close();
}
main();

