const fs = require('fs');
const { Pool } = require('./pool.js');
const base = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const seeds = Array.from({ length: 128 }, (_, i) => 500 + i);
const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;
function withTail(steps) { const g = JSON.parse(JSON.stringify(base)); for (const s of steps) g.q.push(s); return g; }
function conv(slot, type, w) { return [[2, slot, 0, w], [0, slot, type, w], [1, slot, 0, w], [1, slot, 0, w]]; }
(async () => {
  const pool = new Pool(3);
  console.log('base', mean(await pool.evalMean(base, seeds, 3)).toFixed(3), 'qlen', base.q.length);
  const variants = {
    'conv3->cannon w30': conv(3, 1, 30),
    'conv3 w36': conv(3, 1, 36),
    'conv3,12 w34': conv(3, 1, 34).concat(conv(12, 1, 34)),
    'conv3,12,13 w34': conv(3, 1, 34).concat(conv(12, 1, 34), conv(13, 1, 34)),
    'conv3,12,13,14 w36': conv(3, 1, 36).concat(conv(12, 1, 36), conv(13, 1, 36), conv(14, 1, 36)),
    'conv13 lance': conv(13, 3, 34),
    'conv3 lance': conv(3, 3, 34)
  };
  for (const [k, v] of Object.entries(variants)) console.log(k, mean(await pool.evalMean(withTail(v), seeds, 3)).toFixed(3));
  pool.close();
})();

