const { makeFactory, rampartSimulate } = require('./lib.js');
const g = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const f = makeFactory(g);
let n = 0, sum = 0, bad = 0, maxMs = 0, min = 1e9, max = 0, totalMs = 0;
const t00 = Date.now();
for (let s = 1; s <= parseInt(process.argv[3] || '600'); s++) {
  const t0 = Date.now();
  try {
    const r = rampartSimulate(f, s, 12020);
    if (!Number.isFinite(r.score) || r.score <= 0) { bad++; console.log('bad score seed', s, r.score); }
