  } catch (e) { bad++; console.log('EXCEPTION seed', s, e.message); }
  const ms = Date.now() - t0; maxMs = Math.max(maxMs, ms); totalMs += ms;
}
console.log('seeds', n, 'mean', (sum / n).toFixed(3), 'min', min, 'max', max, 'bad', bad, 'max ms/game', maxMs, 'avg ms/game', (totalMs / n).toFixed(1));

