// Independent checks on the built index.html (text-level): script structure, vectors, forbidden tokens, external resources.
const fs = require('fs');
const html = fs.readFileSync(process.argv[2], 'utf8');
function between(re) { const m = re.exec(html); if (!m) throw new Error('missing ' + re); return m[1]; }
const strategySrc = between(/<script id="rampart-strategy">([\s\S]*?)<\/script>/);
const simSrc = between(/<script id="rampart-sim">([\s\S]*?)<\/script>/);
const scripts = html.match(/<script[\s>][\s\S]*?<\/script>/g) || [];
console.log('script tags:', scripts.length, scripts.map(s => s.slice(0, 40).replace(/\n/g, ' ')).join(' | '));
const ext = (html.match(/(?:src|href)=["']https?:[^"']+["']/g) || []);
console.log('external refs:', ext.join(', '));
for (const bad of ['fetch(', 'XMLHttpRequest', 'WebSocket', 'importmap', 'esm.sh', '@import', 'TextureLoader', 'SRGBColorSpace', '<audio', 'new Audio']) if (html.includes(bad)) console.log('FOUND forbidden token', bad);
for (const bad of ['Math.random', 'Date', 'performance', 'window', 'document', 'THREE']) if (strategySrc.includes(bad)) console.log('STRATEGY has forbidden', bad);
for (const bad of ['document', 'THREE', 'window', 'Audio', 'Math.random', 'Date.now']) if (simSrc.includes(bad)) console.log('SIM has forbidden', bad);
// each script must define exactly one top-level function
const topFns = (s) => (s.match(/^function\s+\w+/gm) || []);
console.log('strategy top-level functions:', topFns(strategySrc), 'sim:', topFns(simSrc));
const createStrategy = new Function(strategySrc + '\nreturn createStrategy;')();
const rampartSimulate = new Function(simSrc + '\nreturn rampartSimulate;')();
const A = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return a; } });
let r = rampartSimulate(A, 42, 12020);
console.log('A', r.score, r.fallTick, r.log.length, r.hash, r.hash === '82a5353d' ? 'OK' : 'MISMATCH');
const B = () => ({ plan(s) {
  if (s.wave === 1) return [{ op: 'build', slot: 3, type: 'cannon' }, { op: 'build', slot: 6, type: 'frost' }];
  if (s.wave === 3) return [{ op: 'upgrade', slot: 3 }, { op: 'build', slot: 12, type: 'flak' }];
  if (s.wave === 6) return [{ op: 'build', slot: 8, type: 'lance' }, { op: 'sell', slot: 6 }];
  return [];
} });
r = rampartSimulate(B, 7, 12020);
console.log('B', r.score, r.fallTick, r.log.length, r.hash, r.hash === '2e8858d7' ? 'OK' : 'MISMATCH');
r = rampartSimulate(createStrategy, 42, 2020);
console.log('seed 42 (2020 ticks):', r.score, r.fallTick, r.log.length, r.hash);
// two strategy objects share no state
const s1 = createStrategy(), s2 = createStrategy();
const r1 = rampartSimulate(() => s1, 42, 2020), r2 = rampartSimulate(() => s2, 42, 2020);
console.log('independent instances identical:', r1.hash === r2.hash);

