// distribution tail check: parallel over seed ranges using the pool
const fs = require('fs');
const { Pool } = require('./pool.js');
const files = process.argv.slice(2).filter(a => !a.includes('='));
const args = Object.fromEntries(process.argv.slice(2).filter(a => a.includes('=')).map(a => a.split('=')));
const n = parseInt(args.n || '2000'), s0 = parseInt(args.seed0 || '10000');
(async () => {
  const pool = new Pool(parseInt(args.workers || '7'));
  for (const f of files) {
    const g = JSON.parse(fs.readFileSync(f, 'utf8'));
    const chunk = 50, parts = [];
    for (let i = 0; i < n; i += chunk) {
      const seeds = Array.from({ length: Math.min(chunk, n - i) }, (_, k) => s0 + i + k);
      parts.push(pool.run(g, seeds).then(sc => sc.map((v, k) => [seeds[k], v])));
    }
    const all = (await Promise.all(parts)).flat();
    const sc = all.map(a => a[1]), mean = sc.reduce((a, b) => a + b, 0) / sc.length;
    const sd = Math.sqrt(sc.reduce((a, b) => a + (b - mean) ** 2, 0) / sc.length);
    all.sort((a, b) => a[1] - b[1]);
    console.log(f, 'n', n, 'mean', mean.toFixed(3), 'sd', sd.toFixed(2), 'worst', all.slice(0, 6).map(a => a.join(':')).join(' '), 'p1', all[Math.floor(n * 0.01)][1]);
  }
  pool.close();
})();

