const fs = require('fs');
const { Pool } = require('./pool.js');
const base = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const seeds = Array.from({ length: 600 }, (_, i) => 10000 + i);
const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;
(async () => {
  const pool = new Pool(8);
  const run = async (name, g) => { const sc = await pool.evalMean(g, seeds, 8); console.log(name.padEnd(28), mean(sc).toFixed(3), 'min', Math.min(...sc).toFixed(2)); };
  await run('base', base);
  const g1 = JSON.parse(JSON.stringify(base)); g1.q.forEach(s => s[3] = 0); await run('no gates', g1);
  const g2 = JSON.parse(JSON.stringify(base)); g2.res = [0, 0]; await run('no reserve', g2);
  const g3 = JSON.parse(JSON.stringify(g1)); g3.res = [0, 0]; await run('no gates, no reserve', g3);
  console.log('gates:', base.q.filter(s => s[3] > 0).map(s => s.join('/')).join(' '), 'res', base.res);
  pool.close();
})();

