const vm = require('vm');
const h = require('./harness.js');
const get = (e) => vm.runInThisContext(e);
const scene = get('scene'), renderAt = get('__rampart.renderAt');
const pools = get('[enemyPools, hpBgPool, hpFillPool, blobPool, glowPool, ringPool, beamPool, debrisPool, pipPool]');
const flat = [...pools[0], ...pools.slice(1)];
let frames = 0, bad = 0, over = 0, peak = flat.map(() => 0);
const t0 = Date.now();
for (let t = 0; t <= 100; t += 0.0499) {
  renderAt(Math.min(100, t)); frames++;
  flat.forEach((p, i) => { peak[i] = Math.max(peak[i], p.n); if (p.n >= p.cap) over++; });
  scene.traverse((o) => { if (o.isInstancedMesh) { const a = o.instanceMatrix.array; for (let i = 0; i < o.count * 16; i++) if (!Number.isFinite(a[i])) { bad++; break; } } if (o.isMesh && !o.isInstancedMesh) { const e = o.matrixWorld.elements; for (let i = 0; i < 16; i++) if (!Number.isFinite(e[i])) { bad++; break; } } });
}
console.log('frames', frames, 'non-finite', bad, 'pools at capacity frames', over, 'ms/frame', ((Date.now() - t0) / frames).toFixed(2));
console.log('peak usage per pool:', peak.join(','), ' caps:', flat.map(p => p.cap).join(','));
// scrub determinism: render the same time twice from different histories and compare buffers
function snapshot() { return flat.map(p => Array.from(p.m.slice(0, p.n * 16)).join(',') + '|' + p.n).join('#'); }
renderAt(37.35); const a = snapshot(); renderAt(80); renderAt(12); renderAt(37.35); const b = snapshot();
console.log('scrub determinism (37.35s):', a === b ? 'identical' : 'DIFFERENT');
renderAt(93.1); const c = snapshot(); renderAt(5); renderAt(93.1); console.log('scrub determinism (93.1s):', c === snapshot() ? 'identical' : 'DIFFERENT');

